#!/usr/bin/env node
// Scans assets/fonts/thmanyah for the Thmanyah font files you downloaded
// from font.thmanyah.com and writes src/theme/thmanyah.local.ts so Expo loads them.
// The generated file and the fonts stay on your machine (both are git-ignored / reset).
import { readdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(root, 'assets/fonts/thmanyah');
const out = join(root, 'src/theme/thmanyah.local.ts');

// family keyword in file name → registered family prefix
const families = [
  [/serif[-_ ]?display/i, 'ThmanyahSerifDisplay'],
  [/serif[-_ ]?text/i, 'ThmanyahSerifText'],
  [/sans/i, 'ThmanyahSans'],
];
const weights = ['Black', 'Bold', 'Medium', 'Regular', 'Light'];

const files = readdirSync(dir).filter((f) => /\.(otf|ttf)$/i.test(f));
const entries = [];
for (const f of files) {
  const fam = families.find(([re]) => re.test(f));
  const w = weights.find((x) => new RegExp(x, 'i').test(f));
  if (!fam || !w) continue;
  entries.push(`  '${fam[1]}-${w}': require('../../assets/fonts/thmanyah/${f}'),`);
}

writeFileSync(
  out,
  `// Generated by \`npm run fonts:link\` — do not commit with entries (personal-use font licence).\n` +
    `export const thmanyahFonts: Record<string, number> = {\n${entries.join('\n')}\n};\n`,
);
console.log(`Linked ${entries.length} Thmanyah font file(s).`);
if (!entries.length) console.log('No .otf/.ttf files found in assets/fonts/thmanyah — fallbacks stay active.');
